solution_code:
#include <iostream>

class Temperature {
    const int m_celsius;
public:
    Temperature(int celsius)
        : m_celsius{ celsius }
    {}

    int celsius() const { return m_celsius; }
    int toFahrenheit() const { return m_celsius * 9 / 5 + 32; }
};

void report(const Temperature& t) {
    std::cout << t.celsius() << "C = " << t.toFahrenheit() << "F\n";
}

int main() {
    int c1{}, c2{};
    std::cin >> c1 >> c2;

    report(Temperature{ c1 });
    std::cout << "Quick: " << Temperature{ c2 }.toFahrenheit() << "F\n";
}
